# Apply-Sigma.ps1
# Puts Sigma into CppKAI, using your local repositories:
#
#   1. CppKaiConsoleLib: commit "Console: AddTranslator ..." on branch 'sigma'
#   2. CppKaiCore:       checks your 'sigma' branch has the signature and
#                        GetError commits (you applied those already)
#   3. CppKaiLanguage:   moves CppKAI's copy to GitHub's 264bbc1; your local
#                        8e48e7d ("Apply Clang Format") breaks PiTranslator.h
#   4. CppKAI:           branch 'sigma' with the Sigma commit, CppKaiConsoleLib
#                        added as a submodule, and the submodule bumps
#
# Both patches are embedded (base64, so CRLF line endings survive). The
# script stops before changing anything in a repo that has uncommitted
# changes or a git am in progress, and running it again is safe.
#
# Usage:  pwsh -File .\Apply-Sigma.ps1
#         pwsh -File .\Apply-Sigma.ps1 -Repos D:\code

param(
    [string]$Repos = "$HOME\local\repos",
    [string]$Branch = "sigma",
    [string]$ConsoleLibUrl = "https://github.com/cschladetsch/CppKaiConsoleLib.git"
)

$ErrorActionPreference = "Stop"

$Kai        = Join-Path $Repos "CppKAI"
$ConsoleLib = Join-Path $Repos "CppKaiConsoleLib"
$Core       = Join-Path $Kai "Ext\CppKaiCore"
$Lang       = Join-Path $Kai "Ext\CppKaiLanguage"
$KaiConsole = Join-Path $Kai "Ext\CppKaiConsoleLib"
$LangCommit = "264bbc15d6e0d69ca2e8c0473bbee9ac6be5dee1"

