"@

function Step([string]$message) { Write-Host "`n== $message" -ForegroundColor Cyan }

function Invoke-Git {
    git @args
    if ($LASTEXITCODE -ne 0) { throw "git $($args -join ' ') failed in $(Get-Location)" }
}

function Assert-Repo([string]$path) {
    if (-not (Test-Path "$path\.git")) { throw "Not a git repository: $path" }
}

function Assert-Clean([string]$path) {
    Push-Location $path
    try {
        if (Test-Path (git rev-parse --git-path rebase-apply)) {
            throw "A git am or rebase is in progress in $path. Finish it or run 'git am --abort' first."
        }
        $dirty = git status --porcelain --untracked-files=no --ignore-submodules=all
        if ($dirty) { throw "$path has uncommitted changes; commit or stash them first:`n$($dirty -join "`n")" }
    }
    finally { Pop-Location }
}

function Use-Branch([string]$name) {
    git show-ref --verify --quiet "refs/heads/$name"
    if ($LASTEXITCODE -eq 0) { Invoke-Git switch $name } else { Invoke-Git switch -c $name }
}

function Test-HasCommit([string]$subject) {
    [bool](git log --oneline --fixed-strings --grep $subject)
}

function Write-Patch([string]$base64, [string]$name) {
    $file = Join-Path ([IO.Path]::GetTempPath()) $name
    [IO.File]::WriteAllBytes($file, [Convert]::FromBase64String($base64))
    $file
}

function Apply-Patch([string]$base64, [string]$name) {
    $file = Write-Patch $base64 $name
    git am --keep-cr -3 $file
    if ($LASTEXITCODE -ne 0) {
        Write-Warning "git am stopped in $(Get-Location). Run 'git status', fix the conflict, 'git add <file>', 'git am --continue', then run this script again. Or 'git am --abort' to back out."
        exit 1
    }
    Remove-Item $file -ErrorAction SilentlyContinue
}

Assert-Repo $Kai
Assert-Repo $ConsoleLib
Assert-Repo $Core
Assert-Repo $Lang

# 1 ---------------------------------------------------------------------------
Step "CppKaiConsoleLib: AddTranslator hook on '$Branch'"
Assert-Clean $ConsoleLib
Push-Location $ConsoleLib
try {
    Use-Branch $Branch
    if (Test-HasCommit "Console: AddTranslator for languages beyond Pi and Rho") {
        Write-Host "already applied"
    } else {
        Apply-Patch $ConsoleHookBase64 "kai-console-addtranslator.patch"
    }
    git log --oneline -1
}
finally { Pop-Location }

# 2 ---------------------------------------------------------------------------
Step "CppKaiCore: checking for the Sigma prerequisites"
Push-Location $Core
try {
    $missing = @()
    if (-not (Test-HasCommit "Record static signatures for reflected methods")) { $missing += "Record static signatures for reflected methods" }
    if (-not (Test-HasCommit "ParserCommon::GetError returns the parse error")) { $missing += "ParserCommon::GetError returns the parse error" }
    if ($missing) {
        throw "CppKaiCore ($(git rev-parse --abbrev-ref HEAD)) is missing: $($missing -join '; '). Switch it to your '$Branch' branch and run again."
    }
    git log --oneline -1
}
finally { Pop-Location }

# 3 ---------------------------------------------------------------------------
Step "CppKaiLanguage: GitHub $($LangCommit.Substring(0, 7))"
Assert-Clean $Lang
Push-Location $Lang
try {
    git cat-file -e "$LangCommit^{commit}" 2>$null
    if ($LASTEXITCODE -ne 0) { Invoke-Git fetch origin }
    git cat-file -e "$LangCommit^{commit}" 2>$null
    if ($LASTEXITCODE -ne 0) { throw "Commit $LangCommit not found after fetching origin in $Lang" }
    Invoke-Git checkout --quiet --detach $LangCommit
    git log --oneline -1
}
finally { Pop-Location }

# 4 ---------------------------------------------------------------------------
Step "CppKAI: Sigma on '$Branch'"
Assert-Clean $Kai
Push-Location $Kai
try {
    Use-Branch $Branch

    if (Test-HasCommit "Sigma: statically typed language that compiles to Rho") {
        Write-Host "Sigma commit already applied"
    } else {
        Apply-Patch $SigmaPatchBase64 "kai-sigma.patch"
    }

    # CppKaiConsoleLib as a submodule. It is cloned from your local repo (it is
    # not on GitHub yet) and recorded with the GitHub URL.
    $known = git config -f .gitmodules --get-regexp "submodule\..*\.path" 2>$null |
             Where-Object { $_ -match "Ext/CppKaiConsoleLib$" }
    if (-not $known) {
        if (-not (Test-Path "$KaiConsole\.git")) {
            if (Test-Path $KaiConsole) { throw "$KaiConsole exists but is not a git repository" }
            Invoke-Git clone --quiet --branch $Branch $ConsoleLib $KaiConsole
            Push-Location $KaiConsole
            try {
                Invoke-Git remote rename origin local
                Invoke-Git remote add origin $ConsoleLibUrl
            }
            finally { Pop-Location }
        }
        Invoke-Git submodule add --force $ConsoleLibUrl Ext/CppKaiConsoleLib
        Invoke-Git submodule absorbgitdirs Ext/CppKaiConsoleLib
    } else {
        Push-Location $KaiConsole
        try {
            git remote get-url local 2>$null | Out-Null
            if ($LASTEXITCODE -ne 0) { Invoke-Git remote add local $ConsoleLib }
            Invoke-Git fetch --quiet local
            Invoke-Git checkout --quiet --detach "local/$Branch"
        }
        finally { Pop-Location }
    }

    Invoke-Git add .gitmodules Ext/CppKaiCore Ext/CppKaiLanguage Ext/CppKaiConsoleLib
    git diff --cached --quiet
    if ($LASTEXITCODE -ne 0) {
        Invoke-Git commit --quiet -m "Bump submodules for Sigma" -m "CppKaiCore: sigma branch (method signatures, GetError). CppKaiLanguage: GitHub 264bbc1 (local 8e48e7d broke PiTranslator.h). Add CppKaiConsoleLib (AddTranslator)."
    } else {
        Write-Host "submodules already up to date"
    }

    Write-Host ""
    git log --oneline -3
    Write-Host ""
    git submodule status Ext/CppKaiCore Ext/CppKaiLanguage Ext/CppKaiConsoleLib
}
finally { Pop-Location }

